package dev.slithergoh.pixelmonradar.client;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiEvent;import org.joml.AxisAngle4f;import org.joml.Quaternionf;import java.util.List;
@EventBusSubscriber(modid="pixelmonradar",value=Dist.CLIENT)public final class RadarHud{@SubscribeEvent public static void render(RenderGuiEvent.Post e){if(!RadarSettings.hudEnabled)return;Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.screen!=null)return;List<PokemonInfo>list=PokemonScanner.scan();GuiGraphics g=e.getGuiGraphics();int shown=Math.min(5,list.size()),y=23;g.fill(3,3,174,20+shown*21+(list.size()>shown?11:0),0xA80D1720);g.fill(3,3,174,19,0xC8173A52);g.drawString(mc.font,"RADAR",8,8,0xFFFFFF,true);g.drawString(mc.font,String.valueOf(list.size()),157,8,0x9DE9FF,false);for(int i=0;i<shown;i++){PokemonInfo p=list.get(i);boolean tr=p.entityId()==RadarSettings.trackedEntityId;g.fill(6,y-1,171,y+18,tr?0xB0285747:0x8017232D);if(p.sprite()!=null)g.blit(p.sprite(),9,y+1,0,0,16,16,16,16);int color=p.shiny()?0x55FFFF:p.rare()?0xFFD75A:0xF2F6F8;g.drawString(mc.font,p.name()+" Lv."+p.level(),29,y+1,color,true);g.drawString(mc.font,Math.round(p.distance())+"m"+(p.shiny()?" SHINY":p.rare()?" RARE":""),29,y+10,p.shiny()?0x55FFFF:p.rare()?0xFFD75A:0x9EB0BB,false);y+=21;}if(list.size()>shown)g.drawString(mc.font,"+"+(list.size()-shown)+" more",9,y,0x91A5B3,false);if(RadarSettings.trackedEntityId!=-1)for(PokemonInfo p:list)if(p.entityId()==RadarSettings.trackedEntityId){renderTracker(g,mc,p);break;}}
private static void renderTracker(GuiGraphics g,Minecraft mc,PokemonInfo p){double dx=p.pos().getX()+.5-mc.player.getX(),dz=p.pos().getZ()+.5-mc.player.getZ();double target=Math.toDegrees(Math.atan2(-dx,dz)),rel=wrap(target-mc.player.getYRot());int cx=g.guiWidth()/2;g.fill(cx-102,6,cx+102,54,0xD00D1720);g.fill(cx-102,6,cx+102,9,p.shiny()?0xFF55FFFF:0xFF4AA6D8);if(p.sprite()!=null)g.blit(p.sprite(),cx-94,15,0,0,30,30,30,30);g.drawString(mc.font,p.name()+" Lv."+p.level(),cx-57,15,p.shiny()?0x55FFFF:0xFFFFFF,true);g.drawString(mc.font,Math.round(p.distance())+"m • "+p.pos().getX()+" "+p.pos().getY()+" "+p.pos().getZ(),cx-57,29,0xAFC4CF,false);PoseStack ps=g.pose();ps.pushPose();ps.translate(cx+78,30,0);ps.mulPose(new Quaternionf(new AxisAngle4f((float)Math.toRadians(-rel),0,0,1)));float pulse=(float)(1.0+Math.sin(System.currentTimeMillis()/160.0)*.08);ps.scale(pulse,pulse,1);int c=p.shiny()?0xFF55FFFF:0xFF7EDBFF;g.fill(-3,-14,3,8,c);g.fill(-9,-9,10,-3,c);g.fill(-6,-12,7,-6,c);ps.popPose();}private static double wrap(double a){while(a<=-180)a+=360;while(a>180)a-=360;return a;}}
